import React, { useState, useEffect, useRef } from 'react';
import Button from 'react-bootstrap/Button';
import 'bootstrap/dist/js/bootstrap.bundle.min.js';
import 'bootstrap/dist/css/bootstrap.min.css';
import { Video, Phone, PhoneOff, Calendar, User, FileText, CheckCircle, Clock, AlertCircle, History, Edit } from 'lucide-react';

const API_BASE = 'http://localhost:5000/api';

const DOCTORS = [
  {
    id: 101,
    name: 'Dr. Sarah Johnson',
    email: 'sarah.johnson@telemed.com',
    password: 'doctor123',
    specialization: 'Cardiology',
    description: 'Heart conditions, blood pressure, chest pain, cardiovascular diseases',
    license: 'MD-12345',
    experience: '15 years'
  },
  {
    id: 102,
    name: 'Dr. Michael Chen',
    email: 'michael.chen@telemed.com',
    password: 'doctor123',
    specialization: 'General Surgery',
    description: 'Post-operative care, wound complications, surgical follow-ups',
    license: 'MD-12346',
    experience: '12 years'
  },
  {
    id: 103,
    name: 'Dr. Emily Rodriguez',
    email: 'emily.rodriguez@telemed.com',
    password: 'doctor123',
    specialization: 'Internal Medicine',
    description: 'Diabetes, infections, general health concerns, chronic diseases',
    license: 'MD-12347',
    experience: '10 years'
  },
  {
    id: 104,
    name: 'Dr. David Thompson',
    email: 'david.thompson@telemed.com',
    password: 'doctor123',
    specialization: 'Orthopedics',
    description: 'Bone fractures, joint pain, mobility issues, post-surgery rehabilitation',
    license: 'MD-12348',
    experience: '18 years'
  },
  {
    id: 105,
    name: 'Dr. Lisa Patel',
    email: 'lisa.patel@telemed.com',
    password: 'doctor123',
    specialization: 'Pulmonology',
    description: 'Breathing problems, lung conditions, respiratory infections, COPD',
    license: 'MD-12349',
    experience: '14 years'
  }
];

const App = () => {
  const [user, setUser] = useState(null);
  const [view, setView] = useState('login');
  const [consultations, setConsultations] = useState([]);
  const [activeCall, setActiveCall] = useState(null);

  const localVideoRef = useRef(null);
  const remoteVideoRef = useRef(null);
  const peerConnectionRef = useRef(null);
  const localStreamRef = useRef(null);

  useEffect(() => {
    const storedUser = JSON.parse(sessionStorage.getItem('user') || 'null');
    if (storedUser) {
      setUser(storedUser);
      setView(storedUser.role === 'patient' ? 'patient-dashboard' : 'doctor-dashboard');
      loadConsultations(storedUser);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const loadConsultations = async (currentUser) => {
    try {
      const endpoint = currentUser.role === 'patient' 
        ? `/consultations/patient/${currentUser.id}`
        : `/consultations/doctor/${currentUser.id}`;

      const response = await fetch(API_BASE + endpoint);
      const data = await response.json();
      setConsultations(data);
    } catch (error) {
      const storedConsultations = JSON.parse(sessionStorage.getItem('consultations') || '[]');
      if (currentUser.role === 'patient') {
        setConsultations(storedConsultations.filter(c => c.patient_id === currentUser.id));
      } else {
        setConsultations(storedConsultations.filter(c => c.doctor_id === currentUser.id));
      }
    }
  };

  const LoginForm = () => {
    const [formData, setFormData] = useState({ email: '', password: '' });

    const handleLogin = async (e) => {
      e.preventDefault();

      const doctor = DOCTORS.find(d => d.email === formData.email && d.password === formData.password);

      if (doctor) {
        const doctorUser = {
          id: doctor.id,
          name: doctor.name,
          email: doctor.email,
          role: 'doctor',
          specialization: doctor.specialization
        };
        setUser(doctorUser);
        sessionStorage.setItem('user', JSON.stringify(doctorUser));
        setView('doctor-dashboard');
        loadConsultations(doctorUser);
        return;
      }

      try {
        const response = await fetch(`${API_BASE}/auth/login`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ...formData, role: 'patient' })
        });

        const data = await response.json();
        if (response.ok) {
          setUser(data.user);
          sessionStorage.setItem('user', JSON.stringify(data.user));
          setView('patient-dashboard');
          loadConsultations(data.user);
        } else {
          alert(data.message || 'Login failed');
        }
      } catch (error) {
        alert('Login failed. Please check your credentials or register as a new patient.');
      }
    };

    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl shadow-xl p-8 w-full max-w-md">
          <div className="text-center mb-8">
            <div className="inline-flex items-center justify-center w-16 h-16 bg-blue-600 rounded-full mb-4">
              <Video className="w-8 h-8 text-white" />
            </div>
            <h1 className="text-3xl font-bold text-gray-800">TeleMed Care</h1>
            <p className="text-gray-600 mt-2">Early Readmission Prevention</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Email</label>
              <input
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="your@example.com"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Password</label>
              <input
                type="password"
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="••••••••"
                required
              />
            </div>
            <button
              type="submit"
              className="w-full bg-blue-600 text-white py-3 rounded-lg font-medium hover:bg-blue-700 transition"
            >
              Sign In
            </button>
          </form>

          <div className="mt-6 text-center">
            <button
              onClick={() => setView('register')}
              className="text-blue-600 hover:text-blue-700 text-sm font-medium"
            >
              New Patient? Register Here
            </button>
          </div>

          <div className="mt-8 pt-6 border-t">
            <p className="text-xs text-gray-500 text-center mb-2">Demo Doctor Accounts:</p>
            <div className="text-xs text-gray-600 space-y-1">
              {DOCTORS.slice(0, 2).map(doc => (
                <p key={doc.id} className="text-center">
                  {doc.email} / doctor123
                </p>
              ))}
            </div>
          </div>
        </div>
      </div>
    );
  };

  const RegisterForm = () => {
    const [formData, setFormData] = useState({
      name: '',
      email: '',
      password: '',
      phone: ''
    });

    const handleRegister = async (e) => {
      e.preventDefault();

      try {
        const response = await fetch(`${API_BASE}/auth/register`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ...formData, role: 'patient' })
        });

        const data = await response.json();
        if (response.ok) {
          alert('Registration successful! Please login.');
          setView('login');
        } else {
          alert(data.message || 'Registration failed');
        }
      } catch (error) {
        const newPatient = {
          id: Date.now(),
          ...formData,
          role: 'patient'
        };
        const patients = JSON.parse(sessionStorage.getItem('patients') || '[]');
        patients.push(newPatient);
        sessionStorage.setItem('patients', JSON.stringify(patients));
        alert('Registration successful! Please login.');
        setView('login');
      }
    };

    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl shadow-xl p-8 w-full max-w-md">
          <h1 className="text-2xl font-bold text-gray-800 mb-6 text-center">Patient Registration</h1>

          <form onSubmit={handleRegister} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Full Name</label>
              <input
                type="text"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Email</label>
              <input
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Password</label>
              <input
                type="password"
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Phone</label>
              <input
                type="tel"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                required
              />
            </div>
            <button
              type="submit"
              className="w-full bg-blue-600 text-white py-3 rounded-lg font-medium hover:bg-blue-700 transition"
            >
              Register
            </button>
          </form>

          <div className="mt-6 text-center">
            <button
              onClick={() => setView('login')}
              className="text-blue-600 hover:text-blue-700 text-sm font-medium"
            >
              Already have an account? Login
            </button>
          </div>
        </div>
      </div>
    );
  };

  const PatientDashboard = () => {
    const [activeTab, setActiveTab] = useState('doctors');
    const [showBooking, setShowBooking] = useState(false);
    const [selectedDoctor, setSelectedDoctor] = useState(null);
    const [showReschedule, setShowReschedule] = useState(null);
    const [bookingForm, setBookingForm] = useState({
      symptoms: '',
      discharged_from: '',
      discharge_date: '',
      medications: '',
      urgency: 'normal',
      preferred_date: '',
      preferred_time: ''
    });

    const handleBookConsultation = async (e) => {
      e.preventDefault();
      try {
        const response = await fetch(`${API_BASE}/consultations`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            patient_id: user.id,
            doctor_id: selectedDoctor.id,
            doctor_name: selectedDoctor.name,
            specialization: selectedDoctor.specialization,
            ...bookingForm
          })
        });

        if (response.ok) {
          alert('Consultation booked successfully!');
          setShowBooking(false);
          setSelectedDoctor(null);
          loadConsultations(user);
        }
      } catch (error) {
        const newConsultation = {
          id: Date.now(),
          patient_id: user.id,
          doctor_id: selectedDoctor.id,
          doctor_name: selectedDoctor.name,
          specialization: selectedDoctor.specialization,
          status: 'pending',
          ...bookingForm,
          created_at: new Date().toISOString()
        };
